.btn:focus-visible, .link:focus-visible { outline: 3px solid #2965f1; outline-offset: 3px; }
.link { font: 16px sans-serif; margin-left: 12px; }
.sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

